<?php /* expects $att (rows), $kind via $n/$t context: kind and ref set by caller through $att_kind/$att_ref */ $att_kind = isset($n) && !isset($t) ? 'note' : 'task'; $att_ref = (int) (($att_kind === 'note' ? $n['id'] : $t['id'])); $att_write = $att_kind === 'task' || !empty($mine); ?>
<?php foreach ($att as $a): $img = str_starts_with($a['mime'], 'image/'); ?><div class="comment"><?php if ($img): ?><a href="/staff/attachments/<?= (int) $a['id'] ?>"><img src="/staff/attachments/<?= (int) $a['id'] ?>?inline=1" alt="<?= e($a['orig_name']) ?>" style="max-width:160px;max-height:110px;display:block;margin-bottom:4px;border-radius:6px"></a><?php endif; ?><a href="/staff/attachments/<?= (int) $a['id'] ?>"><?= e($a['orig_name']) ?></a> <span class="muted">(<?= e(fmt_bytes((int) $a['size_bytes'])) ?>)</span><br><span class="who"><?= e((string) ($a['uname'] ?? '')) ?> &middot; <?= e(fmt_dt($a['created_at'])) ?></span>
<?php if ((int) $a['uploaded_by'] === (int) $u['id'] || can('team.manage')): ?><form method="post" action="/staff/attachments/<?= (int) $a['id'] ?>/delete" class="inline"><?= csrf_field() ?><button class="btn link" data-confirm="Remove this file?">Remove</button></form><?php endif; ?></div><?php endforeach; ?>
<?php if (!$att): ?><p class="muted">No files.</p><?php endif; ?>
<?php if ($att_write): ?><form method="post" action="/staff/attachments" enctype="multipart/form-data" class="mt"><?= csrf_field() ?><input type="hidden" name="kind" value="<?= e($att_kind) ?>"><input type="hidden" name="ref_id" value="<?= $att_ref ?>"><label for="af<?= $att_kind ?>">Attach files (images, PDF, Office files, text, zip; up to 15 MB each)</label><input id="af<?= $att_kind ?>" type="file" name="files[]" multiple><button class="btn alt sm">Upload</button></form><?php endif; ?>
